// Global compile-time Firebase configuration constants injected by the Angular build system.
// Values are provided via environment variables / GitHub Repository Secrets during CI builds.
declare const FIREBASE_API_KEY: string | undefined;
declare const FIREBASE_AUTH_DOMAIN: string | undefined;
declare const FIREBASE_PROJECT_ID: string | undefined;
declare const FIREBASE_STORAGE_BUCKET: string | undefined;
declare const FIREBASE_MESSAGING_SENDER_ID: string | undefined;
declare const FIREBASE_APP_ID: string | undefined;
declare const FIREBASE_MEASUREMENT_ID: string | undefined;
declare const FIREBASE_DATABASE_ID: string | undefined;
declare const FIREBASE_OAUTH_CLIENT_ID: string | undefined;
